"""Bounded checkpoint cache reconstruction and monotonic timing accounting; no CAD or process enumeration."""
import json, os, subprocess, uuid
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
    folder=ROOT/'runs/v042a3-policy'/uuid.uuid4().hex[:8];folder.mkdir(parents=True)
    source=folder/'Checks.cs'
    source.write_text('using System;using System.IO;using System.Linq;class Checks{\n static int n;static void Check(bool value){n++;if(!value)throw new Exception("check "+n);}\n static void Bad(string line){try{ReplayCsv.Parse(line);}catch(Exception e){Check(e.Message=="REPLAY_CSV_INVALID_QUOTING");return;}throw new Exception("invalid quoting accepted");}\n static int Main(){try{\n Check(ReplayCsv.Parse("a,b,").SequenceEqual(new[]{"a","b",""}));\n Check(ReplayCsv.Parse("\\"零件,1\\",\\"a\\"\\"b\\",,9").SequenceEqual(new[]{"零件,1","a\\"b","","9"}));\n Check(ReplayCsv.Parse("\\"\\"\\"\\"").Single()=="\\"");Bad("a\\"b");Bad("\\"a\\"b");Bad("\\"a");\n Check(ReplayCsv.Allows(31,6,15,1,30));Check(ReplayCsv.Allows(1801,55,1800,30,60));\n Check(!ReplayCsv.Allows(1801,56,0,30,60));Check(!ReplayCsv.Allows(31,6,31,1,30));Check(!ReplayCsv.Allows(31,6,-1,1,30));\n foreach(double d in new[]{double.NaN,double.PositiveInfinity,0,-1,30.01,1.01})Check(!ReplayCsv.Allows(31,6,0,d,30));\n Check(!ReplayCsv.Allows(31,6,0,1,2500));Check(!ReplayCsv.Allows(31,0,0,1,30));Check(!ReplayCsv.Allows(31,501,0,1,30));\n\nstring owner=Path.Combine(Path.GetTempPath(),"branch-boundary-policy"),id="user_"+new string(\'a\',32),worker=Path.Combine(owner,"runs","probes","reset_0123abcd"),directory=Path.Combine(owner,"experiments","user_assemblies",id.Substring(5)),asm=Path.Combine(directory,"files","model.SLDASM"),part=Path.Combine(directory,"files","part.SLDPRT");\n Check(ResetBranchBoundary.Validate(worker,id,directory,asm,new[]{asm,part},"reset_branch","incomplete")==directory);\n foreach(int mode in Enumerable.Range(0,11)){try{ResetBranchBoundary.Validate(mode==0?worker+"bad":worker,mode==1?"../bad":id,mode==2?owner:directory,mode==3?part:asm,mode==4?new[]{asm,asm}:mode==5?new[]{asm,Path.Combine(directory,"evil.SLDPRT")}:mode==6?new[]{asm,Path.Combine(directory,"files","bad.exe")}:mode==7?new[]{asm,Path.Combine(directory,"files","other.SLDASM")}:mode==8?new[]{asm,"relative.SLDPRT"}:new[]{asm,part},mode==9?"compatibility_probe":"reset_branch",mode==10?"complete":"incomplete");throw new Exception("invalid boundary accepted");}catch(Exception e){Check(e.Message=="RESET_BRANCH_WORKER_BOUNDARY_INVALID");}}\n long clock=0;var budget=new GeometryScanBudget(10,()=>clock);Check(budget.Continue());clock=9;Check(budget.Continue());clock=10;Check(!budget.Continue());clock=0;Check(!budget.Continue());\nvar finished=new GeometryScanBudget(10,()=>clock);clock=4;finished.Finish();clock=100;Check(finished.Export(null,0).GetType().GetProperty(\"elapsed_ms\").GetValue(finished.Export(null,0),null).Equals(4L));\nvar guidance=StudyCacheBudget.ResetGuidance(\"fast\",5,2500,1,false);Check(guidance.GetType().GetProperty(\"new_model_reset_option\").GetValue(guidance,null)!=null);\nvar blocked=StudyCacheBudget.ResetGuidance(\"too_long\",31,2500,1,false);Check(blocked.GetType().GetProperty(\"new_model_reset_option\").GetValue(blocked,null)==null);\nConsole.WriteLine(n);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}\n',encoding='utf-8',newline='\n')
    exe=folder/'Checks.exe';compiler=Path(os.environ['WINDIR'])/'Microsoft.NET/Framework64/v4.0.30319/csc.exe'
    subprocess.run([str(compiler),'/nologo','/reference:System.Web.Extensions.dll','/out:'+str(exe)]+[str(ROOT/'executor'/n) for n in ['ReplayCsv.cs','ResetBranchBoundary.cs','GeometryScanBudget.cs','StudyCacheBudget.cs']]+[str(source)],check=True)
    count=int(subprocess.check_output([str(exe)],text=True).strip());result={'all_passed':True,'checks':count,'cad_connection_used':False}
    (folder/'result.json').write_text(json.dumps(result,indent=2),encoding='utf-8');print(json.dumps(result))
if __name__=='__main__':main()
